// Edit these values. The token is the credential "Crystalline token"
// (Bearer Auth) on the MCP Client Tool.
const body = $input.first().json.body || {};
if (typeof body.text !== 'string' || body.text.trim() === '') {
  throw new Error('Send JSON with a text field.');
}
return [{
  json: {
    // The server's address as n8n reaches it, without a trailing slash.
    url: 'https://crystalline.example.com',
    // The domain new knowledge goes to, unless the request names one.
    domain: typeof body.domain === 'string' && body.domain ? body.domain : 'inbox',
    text: body.text,
  },
}];
